/** A thing to undo when the extension stops. */
interface Disposable { dispose(): void }
type TideEvent = "open" | "save" | "run" | "project" | "settings";
/** The API a TIde extension's activate(tide) gets. */
interface Tide {
  /** TIde's version, such as "2.2.0", or "dev" in a browser or a development build. */
  readonly version: string;
  /** This extension: its id, folder ("tide:<id>" when it runs from TIde itself, in a browser) and extension.json. */
  readonly extension: { id: string; dir: string; manifest: any };
  /** Monaco, the editor TIde is built on, for anything else: monaco.languages, monaco.editor… */
  readonly monaco: any;
  /** Add things here to undo them when the extension is turned off. Everything tide.* returns is added already. */
  readonly subscriptions: { push(...items: Disposable[]): void };
  readonly commands: {
    /**
     * Adds a command to the Run menu and the editor's right-click menu. With when, it shows only
     * in the projects it's for: { project: true } while a folder is open, { calculator: ["nspire"] }
     * in a project for those calculators, { language: ["c", "cpp"] } in one in those languages
     * (tide.json's names). shortcut is the hint the menus show; it doesn't bind a key.
     */
    register(
      id: string,
      label: string,
      run: () => unknown,
      options?: {
        shortcut?: string;
        when?: { project?: boolean; calculator?: ("ce" | "plus" | "nspire")[]; language?: string[] };
      },
    ): Disposable;
  };
  /** IntelliSense for any editor language: "tibasic", "c", "cpp", "ez80", "z80", "python" (py2ez80), "tipython", "lua", or one an extension adds. */
  readonly languages: {
    /** provider.provideCompletionItems(model, position) returns { suggestions: [...] }, as in Monaco. */
    completions(language: string, provider: { provideCompletionItems(model: any, position: any): any; triggerCharacters?: string[] }): Disposable;
    /** provider.provideHover(model, position) returns { contents: [{ value: "markdown" }] }, or null. */
    hover(language: string, provider: { provideHover(model: any, position: any): any }): Disposable;
    signatureHelp(language: string, provider: { provideSignatureHelp(model: any, position: any): any; signatureHelpTriggerCharacters?: string[] }): Disposable;
    /** Turns on TIde's own IntelliSense for a language: completions, hover help, signature help and more. */
    builtIn(language: "tibasic" | "c" | "ez80" | "python" | "tipython"): Disposable;
    /** Shows problems in a file (squiggles and the status bar). */
    markers(model: any, markers: { startLineNumber: number; startColumn: number; endLineNumber: number; endColumn: number; message: string; severity: number }[]): void;
  };
  /** Runs fn when a file or program opens or is saved, a program runs, the active folder changes or closes, or settings change. */
  on(event: TideEvent, fn: (detail: any) => void): Disposable;
  /** Runs a command line in the open folder (or 'dir'), like tide.json's build. Output goes to the Output tab. */
  run(line: string, dir?: string): Promise<{ ok: boolean; output: string }>;
  /** Shows text in the status bar. */
  message(text: string): void;
  /** The settings in use. */
  settings(): Readonly<Record<string, unknown>>;
  /** The open folder (in a workspace, the active one), if any. */
  project(): { root: string; name: string; calculator: string; language?: string } | null;
  readonly editor: {
    /** The open file or program: its name, path (null for programs) and language. */
    file(): { name: string; path: string | null; language: string } | null;
    text(): string;
    setText(text: string): void;
    /** The selected text. */
    selection(): string;
    /** Replaces the selection, or inserts at the cursor. */
    insert(text: string): void;
  };
  readonly calculator: {
    show(): Promise<void>;
    /** A calculator macro, as in tide.json: macro("key.press", "enter"), macro("program.run", "HELLO"). */
    macro(name: "key.press" | "key.type" | "program.run" | "program.open" | "app.open" | "wait", arg?: string): Promise<void>;
    /** Which kind of calculator is running, starting it: "ce", "plus", "nspire", "other", or null. */
    family(): Promise<string | null>;
    /** Sends files (such as a built .tns) to the calculator. */
    send(files: { name: string; bytes: Uint8Array }[]): Promise<void>;
  };
  readonly files: {
    /** Reads a file as text. Relative paths are from this extension's folder. */
    read(path: string): Promise<string>;
    /** Reads a file's bytes. Relative paths are from the open folder; absolute paths work too. */
    readBinary(path: string): Promise<Uint8Array>;
    /** Writes a text file. Relative paths are from the open folder; absolute paths work too. */
    write(path: string, text: string): Promise<void>;
    /** Opens a file in a tab. Relative paths are from the open folder. */
    open(path: string): Promise<void>;
  };
}
